const response = $json;
const raw = response.choices?.[0]?.message?.content;
if (typeof raw !== 'string') throw new Error('AI response did not contain message content');
let transaction;
try { transaction = JSON.parse(raw); } catch { throw new Error('AI response was not valid JSON'); }
const source = $('Receive dictated Teams message').first().json.body ?? {};
transaction.source_transcript = String(source.text ?? '');
if (!Array.isArray(transaction.missing_or_ambiguous)) transaction.missing_or_ambiguous = [];
return [{ json: { transaction, source_message_id: source.messageId ? String(source.messageId) : null, source_channel: 'teams_dictation', submitted_by: source.sender ? String(source.sender) : null, idempotency_key: source.messageId ? 'teams:' + String(source.messageId) : null } }];
